node -e "
const { DatabaseSync } = require('node:sqlite');
const db = new DatabaseSync('/workspace/world.db');

// Check warranties table schema
const schema = db.prepare(\"SELECT sql FROM sqlite_master WHERE name='warranties'\").get();
console.log('=== SCHEMA ===');
console.log(schema.sql);

// Look for warranties related to the product or order
const all = db.prepare(\"SELECT * FROM warranties WHERE order_id = 'ORD-5B048F' OR product_id = 'PROD-B98D14'\").all();
console.log('\n=== MATCHING WARRANTIES ===');
console.log(JSON.stringify(all, null, 2));

if (all.length === 0) {
  // Check all warranties
  const allW = db.prepare('SELECT * FROM warranties').all();
  console.log('\n=== ALL WARRANTIES ===');
  console.log(JSON.stringify(allW, null, 2));
}
"
